"use client";

/* eslint-disable @next/next/no-html-link-for-pages */

import Image from "next/image";
import { useRouter } from "next/navigation";
import {
  AlertTriangle, BadgeCheck, Bookmark, Check, ChevronDown, ChevronRight,
  CircleHelp, Clock3, CreditCard, Download, ExternalLink, FileImage, Gauge, HelpCircle,
  History, ImageOff, ListFilter, LoaderCircle, LockKeyhole,
  LogOut, MapPin, Menu, PackageCheck, PackageSearch, RefreshCw, Search,
  Settings, ShieldAlert, ShieldCheck, SlidersHorizontal, Sparkles, Trash2, TrendingUp,
  Upload, UserRound, WalletCards, X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState, useTransition } from "react";
import {
  deleteAccountAction, signOutAction, signOutOtherSessionsAction, updatePasswordAction,
  updateProfileAction, updateSettingsAction,
} from "@/app/app/actions";
import { appDeals, type AppDeal } from "@/lib/app-data";
import { cn } from "@/lib/utils";
import type { AccountProfile, CreditSummary, UserSettings } from "@/components/software-app";

type PrimaryPage = "find" | "scanner" | "saved";
type MenuPage = "profile" | "membership" | "settings" | "help";
type AppPage = PrimaryPage | MenuPage;
type SearchState = "ready" | "loading" | "results" | "empty" | "error";
type ScanState = "ready" | "preview" | "analysing" | "identified" | "error";
type SavedStatus = "Interested" | "Contacted" | "Purchased" | "Passed";
type SavedMeta = Record<string, { status: SavedStatus; note: string }>;
type Taxon = { name: string; children?: Taxon[] };
type DashboardSnapshot = {
  savedIds: string[];
  savedMeta: SavedMeta;
  unlockedIds: string[];
  onboardingSeen: boolean;
};

const dashboardStorageVersion = 1;

function dashboardStorageKey(email: string) {
  return `flipbot.dashboard.v${dashboardStorageVersion}.${email.trim().toLowerCase()}`;
}

function readDashboardSnapshot(email: string): DashboardSnapshot | null {
  try {
    const raw = window.localStorage.getItem(dashboardStorageKey(email));
    if (!raw) return null;
    const value = JSON.parse(raw) as Partial<DashboardSnapshot>;
    if (!Array.isArray(value.savedIds) || !Array.isArray(value.unlockedIds) || !value.savedMeta || typeof value.savedMeta !== "object") return null;
    const validIds = new Set(appDeals.map((deal) => deal.id));
    const validStatuses = new Set<SavedStatus>(["Interested", "Contacted", "Purchased", "Passed"]);
    const savedIds = value.savedIds.filter((id): id is string => typeof id === "string" && validIds.has(id));
    const unlockedIds = value.unlockedIds.filter((id): id is string => typeof id === "string" && validIds.has(id));
    const savedMeta = Object.fromEntries(Object.entries(value.savedMeta).flatMap(([id, item]) => {
      const candidate = item as { status?: unknown; note?: unknown };
      return validIds.has(id) && validStatuses.has(candidate.status as SavedStatus) && typeof candidate.note === "string"
        ? [[id, { status: candidate.status as SavedStatus, note: candidate.note.slice(0, 500) }]]
        : [];
    }));
    return { savedIds, unlockedIds, savedMeta, onboardingSeen: value.onboardingSeen === true };
  } catch {
    return null;
  }
}

const navigation = [
  { id: "find" as const, label: "Find a Deal", icon: PackageSearch },
  { id: "scanner" as const, label: "Scanner", icon: Search },
  { id: "saved" as const, label: "Saved Deals", icon: Bookmark },
];

const taxonomy: Taxon[] = [
  { name: "Technology", children: [
    { name: "Phones", children: [
      { name: "Apple", children: [{ name: "iPhone", children: [
        { name: "iPhone 15 Pro Max", children: [{ name: "128GB" }, { name: "256GB" }, { name: "512GB" }] },
        { name: "iPhone 15 Pro", children: [{ name: "128GB" }, { name: "256GB" }] },
        { name: "iPhone 13", children: [{ name: "128GB" }, { name: "256GB" }] },
      ] }] },
      { name: "Samsung", children: [{ name: "Galaxy S Series" }, { name: "Galaxy Z Series" }] },
    ] },
    { name: "Laptops", children: [{ name: "Apple MacBook" }, { name: "Windows laptops" }, { name: "Chromebooks" }] },
    { name: "Audio", children: [{ name: "Headphones" }, { name: "Speakers" }] },
    { name: "Gaming", children: [{ name: "Consoles" }, { name: "Games" }, { name: "Accessories" }] },
  ] },
  { name: "Bikes", children: [{ name: "Mountain bikes" }, { name: "Road bikes" }, { name: "Electric bikes" }, { name: "BMX" }] },
  { name: "Home & Garden", children: [{ name: "Power tools" }, { name: "Furniture" }, { name: "Garden equipment" }] },
  { name: "Collectables", children: [{ name: "Trading cards" }, { name: "Watches" }, { name: "Sneakers" }] },
];

export function FlipbotDashboard({ initialProfile, initialUserSettings, initialCredits }: { initialProfile: AccountProfile; initialUserSettings: UserSettings; initialCredits: CreditSummary }) {
  const [page, setPage] = useState<AppPage>("find");
  const [mobileMenu, setMobileMenu] = useState(false);
  const [profileMenu, setProfileMenu] = useState(false);
  const [onboarding, setOnboarding] = useState(false);
  const [onboardingSeen, setOnboardingSeen] = useState(false);
  const [storageReady, setStorageReady] = useState(false);
  const [selectedDeal, setSelectedDeal] = useState<AppDeal | null>(null);
  const [savedIds, setSavedIds] = useState<string[]>(["sony-xm5", "macbook-m2"]);
  const [savedMeta, setSavedMeta] = useState<SavedMeta>({
    "sony-xm5": { status: "Interested", note: "Ask whether the case and charging cable are included." },
    "macbook-m2": { status: "Contacted", note: "Check battery health and confirm it is signed out of iCloud." },
  });
  const [unlockedIds, setUnlockedIds] = useState<string[]>([]);
  const [unlockTarget, setUnlockTarget] = useState<AppDeal | null>(null);
  const [toast, setToast] = useState<string | null>(null);
  const [profile, setProfile] = useState(initialProfile);
  const [settings, setSettings] = useState(initialUserSettings);
  const [isPending, startTransition] = useTransition();
  const profileRef = useRef<HTMLDivElement>(null);

  const savedDeals = useMemo(() => appDeals.filter((deal) => savedIds.includes(deal.id)), [savedIds]);
  const title: Record<AppPage, string> = { find: "Find a Deal", scanner: "Scanner", saved: "Saved Deals", profile: "Profile & Security", membership: "Membership & Credits", settings: "Settings", help: "Help centre" };

  useEffect(() => {
    function dismiss(event: MouseEvent) { if (!profileRef.current?.contains(event.target as Node)) setProfileMenu(false); }
    function escape(event: KeyboardEvent) { if (event.key === "Escape") { setProfileMenu(false); setMobileMenu(false); setSelectedDeal(null); setUnlockTarget(null); setOnboarding(false); } }
    document.addEventListener("mousedown", dismiss); document.addEventListener("keydown", escape);
    return () => { document.removeEventListener("mousedown", dismiss); document.removeEventListener("keydown", escape); };
  }, []);

  useEffect(() => {
    let active = true;
    queueMicrotask(() => {
      if (!active) return;
      const snapshot = readDashboardSnapshot(initialProfile.email);
      if (snapshot) {
        setSavedIds(snapshot.savedIds);
        setSavedMeta(snapshot.savedMeta);
        setUnlockedIds(snapshot.unlockedIds);
        setOnboardingSeen(snapshot.onboardingSeen);
      } else {
        setOnboarding(true);
      }
      setStorageReady(true);
    });
    return () => { active = false; };
  }, [initialProfile.email]);

  useEffect(() => {
    if (!storageReady) return;
    const snapshot: DashboardSnapshot = { savedIds, savedMeta, unlockedIds, onboardingSeen };
    try {
      window.localStorage.setItem(dashboardStorageKey(initialProfile.email), JSON.stringify(snapshot));
    } catch {
      // The dashboard remains usable when browser storage is blocked or full.
    }
  }, [initialProfile.email, onboardingSeen, savedIds, savedMeta, storageReady, unlockedIds]);

  function notify(message: string) { setToast(message); window.setTimeout(() => setToast(null), 2600); }
  function navigate(next: AppPage) { setPage(next); setMobileMenu(false); setProfileMenu(false); window.scrollTo({ top: 0, behavior: settings.reducedMotion ? "auto" : "smooth" }); }
  function toggleSaved(deal: AppDeal) {
    const removing = savedIds.includes(deal.id);
    setSavedIds((ids) => removing ? ids.filter((id) => id !== deal.id) : [deal.id, ...ids]);
    if (!removing) setSavedMeta((meta) => ({ ...meta, [deal.id]: { status: "Interested", note: "" } }));
    notify(removing ? "Removed from Saved Deals" : "Saved to Saved Deals");
  }
  function confirmUnlock() {
    if (!unlockTarget) return;
    setUnlockedIds((ids) => ids.includes(unlockTarget.id) ? ids : [...ids, unlockTarget.id]);
    if (!savedIds.includes(unlockTarget.id)) toggleSaved(unlockTarget);
    setUnlockTarget(null); notify("Buyer-price preview unlocked and saved with this deal");
  }
  function closeOnboarding() { setOnboarding(false); setOnboardingSeen(true); }
  function saveOnboardingSettings(next: UserSettings) {
    setSettings(next);
    startTransition(async () => notify((await updateSettingsAction(next)).message));
  }

  if (!storageReady) {
    return <main className="grid min-h-screen place-items-center bg-[#020308] px-6 text-white"><div role="status" className="flex items-center gap-3 text-sm font-medium text-slate-400"><LoaderCircle className="h-5 w-5 animate-spin text-blue-300" />Loading your workspace…</div></main>;
  }

  return <main className={cn("min-h-screen bg-[#020308] text-white selection:bg-blue-500/35", settings.compactCards && "dashboard-compact")}>
    <a href="#workspace" className="sr-only z-[100] rounded-lg bg-blue-600 p-3 focus:not-sr-only focus:fixed focus:left-4 focus:top-4">Skip to workspace</a>
    <div className="pointer-events-none fixed inset-0 bg-[radial-gradient(circle_at_48%_-10%,rgba(36,107,253,.16),transparent_34rem)]" />
    <DesktopSidebar page={page} navigate={navigate} />
    {mobileMenu ? <MobileMenu page={page} navigate={navigate} close={() => setMobileMenu(false)} /> : null}
    <div className="relative min-h-screen md:pl-[232px]">
      <header className="fixed inset-x-0 top-0 z-30 border-b border-white/[0.07] bg-[#020308]/92 backdrop-blur-xl md:left-[232px]">
        <div className="flex h-[72px] items-center gap-3 px-4 sm:px-6 lg:px-8">
          <button onClick={() => setMobileMenu(true)} className="control md:hidden" aria-label="Open navigation"><Menu className="h-5 w-5" /></button>
          <h1 className="min-w-0 flex-1 truncate text-lg font-semibold tracking-[-0.02em]">{title[page]}</h1>
          <div className="hidden items-center gap-2 lg:flex">
            <button onClick={() => navigate("membership")} className="chip"><Gauge className="h-4 w-4 text-blue-300" />{(initialCredits.subscriptionCredits + initialCredits.purchasedCredits).toLocaleString("en-GB")} credits</button>
            <button onClick={() => navigate("membership")} className="primary-button min-h-10 px-4">Credits</button>
            <button onClick={() => navigate("membership")} className="chip font-semibold text-blue-100">{profile.plan}</button>
          </div>
          <div className="relative" ref={profileRef}>
            <button onClick={() => setProfileMenu((open) => !open)} aria-expanded={profileMenu} aria-haspopup="menu" className="flex h-11 items-center gap-2 rounded-xl border border-white/[0.08] bg-white/[0.03] px-2 hover:bg-white/[0.06]" aria-label="Open profile menu"><Avatar name={profile.name} /><ChevronDown className="hidden h-4 w-4 text-slate-400 sm:block" /></button>
            {profileMenu ? <ProfileMenu profile={profile} navigate={navigate} startSetup={() => { setOnboarding(true); setProfileMenu(false); }} onSignOut={() => startTransition(async () => signOutAction())} pending={isPending} /> : null}
          </div>
        </div>
      </header>
      <div id="workspace" className="mx-auto max-w-[1480px] px-4 pb-28 pt-[96px] sm:px-6 md:pb-10 lg:px-8" tabIndex={-1}>
        {page === "find" && <FindDeals settings={settings} savedIds={savedIds} onOpen={setSelectedDeal} onToggleSaved={toggleSaved} />}
        {page === "scanner" && <Scanner onOpen={setSelectedDeal} />}
        {page === "saved" && <Saved deals={savedDeals} meta={savedMeta} setMeta={setSavedMeta} unlockedIds={unlockedIds} onOpen={setSelectedDeal} onToggleSaved={toggleSaved} onFind={() => navigate("find")} />}
        {page === "profile" && <AccountCenter profile={profile} setProfile={setProfile} notify={notify} />}
        {page === "membership" && <Membership profile={profile} credits={initialCredits} notify={notify} />}
        {page === "settings" && <SettingsCenter settings={settings} setSettings={setSettings} notify={notify} />}
        {page === "help" && <HelpCenter navigate={navigate} />}
      </div>
    </div>
    <MobileBottom page={page} navigate={navigate} />
    {selectedDeal && <DealSheet deal={selectedDeal} saved={savedIds.includes(selectedDeal.id)} unlocked={unlockedIds.includes(selectedDeal.id)} close={() => setSelectedDeal(null)} toggleSaved={() => toggleSaved(selectedDeal)} requestUnlock={() => setUnlockTarget(selectedDeal)} />}
    {unlockTarget && <UnlockDialog deal={unlockTarget} cancel={() => setUnlockTarget(null)} confirm={confirmUnlock} />}
    {onboarding && <Onboarding close={closeOnboarding} settings={settings} setSettings={saveOnboardingSettings as React.Dispatch<React.SetStateAction<UserSettings>>} notify={notify} />}
    {toast && <div role="status" aria-live="polite" className="fixed bottom-24 left-1/2 z-[90] w-[min(92vw,420px)] -translate-x-1/2 rounded-xl border border-blue-300/20 bg-[#081426] px-4 py-3 text-center text-sm font-semibold shadow-[0_18px_50px_rgba(0,0,0,.45)] md:bottom-6">{toast}</div>}
  </main>;
}

function DesktopSidebar({ page, navigate }: { page: AppPage; navigate: (page: AppPage) => void }) { return <aside className="fixed inset-y-0 left-0 z-40 hidden w-[232px] border-r border-white/[0.07] bg-[#04070d]/96 p-4 md:block"><div className="flex h-full flex-col"><Brand /> <nav aria-label="Primary" className="mt-8 space-y-1">{navigation.map((item) => <NavButton key={item.id} item={item} active={page === item.id} onClick={() => navigate(item.id)} />)}</nav><div className="mt-auto px-2 text-xs leading-5 text-slate-500">Find, value and save resale opportunities.</div></div></aside>; }
function Brand() { return <div className="flex h-11 items-center gap-3 px-2"><span className="grid h-10 w-10 place-items-center rounded-xl border border-blue-300/20 bg-blue-500/10 text-lg font-black text-blue-200">F</span><span className="font-semibold tracking-[0.14em]">FLIPBOT</span></div>; }
function NavButton({ item, active, onClick }: { item: typeof navigation[number]; active: boolean; onClick: () => void }) { const Icon = item.icon; return <button onClick={onClick} aria-current={active ? "page" : undefined} className={cn("flex min-h-12 w-full items-center gap-3 rounded-xl px-3 text-left text-sm font-medium text-slate-400 transition hover:bg-white/[0.04] hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-blue-400", active && "bg-blue-500/12 text-blue-100 ring-1 ring-blue-300/15")}><Icon className="h-[18px] w-[18px]" />{item.label}</button>; }
function MobileMenu({ page, navigate, close }: { page: AppPage; navigate: (page: AppPage) => void; close: () => void }) { return <div className="fixed inset-0 z-50 bg-black/70 md:hidden" role="dialog" aria-modal="true" aria-label="Navigation"><aside className="h-full w-[290px] border-r border-white/[0.08] bg-[#04070d] p-4"><div className="flex items-center justify-between"><Brand /><button onClick={close} className="control" aria-label="Close navigation"><X className="h-5 w-5" /></button></div><nav className="mt-8 space-y-1">{navigation.map((item) => <NavButton key={item.id} item={item} active={page === item.id} onClick={() => navigate(item.id)} />)}</nav></aside></div>; }
function MobileBottom({ page, navigate }: { page: AppPage; navigate: (page: AppPage) => void }) { return <nav aria-label="Mobile primary" className="fixed inset-x-3 bottom-3 z-40 grid grid-cols-3 rounded-2xl border border-white/[0.09] bg-[#070a11]/95 p-1.5 shadow-[0_18px_50px_rgba(0,0,0,.5)] md:hidden">{navigation.map((item) => { const Icon = item.icon; const active = page === item.id; return <button key={item.id} aria-current={active ? "page" : undefined} onClick={() => navigate(item.id)} className={cn("flex min-h-14 flex-col items-center justify-center gap-1 rounded-xl text-[11px] font-medium text-slate-500", active && "bg-blue-500/13 text-blue-100")}><Icon className="h-5 w-5" />{item.label}</button>; })}</nav>; }
function Avatar({ name }: { name: string }) { return <span className="grid h-8 w-8 place-items-center rounded-lg bg-blue-500/15 text-sm font-semibold text-blue-100">{name.slice(0, 1).toUpperCase()}</span>; }
function ProfileMenu({ profile, navigate, startSetup, onSignOut, pending }: { profile: AccountProfile; navigate: (page: AppPage) => void; startSetup: () => void; onSignOut: () => void; pending: boolean }) { const items = [{ id: "profile" as const, label: "Profile & security", icon: UserRound }, { id: "membership" as const, label: "Membership & credits", icon: CreditCard }, { id: "settings" as const, label: "Settings", icon: Settings }, { id: "help" as const, label: "Help centre", icon: CircleHelp }]; return <div role="menu" className="absolute right-0 top-14 w-72 overflow-hidden rounded-2xl border border-white/[0.1] bg-[#080b13] p-2 shadow-[0_22px_70px_rgba(0,0,0,.55)]"><div className="border-b border-white/[0.07] px-3 py-3"><p className="truncate text-sm font-semibold">{profile.name}</p><p className="mt-1 truncate text-xs text-slate-500">{profile.email}</p></div><div className="py-2">{items.map((item) => { const Icon = item.icon; return <button role="menuitem" key={item.id} onClick={() => navigate(item.id)} className="menu-item"><Icon className="h-4 w-4 text-slate-500" />{item.label}</button>; })}<button role="menuitem" onClick={startSetup} className="menu-item"><Sparkles className="h-4 w-4 text-slate-500" />Setup guide</button></div><button role="menuitem" onClick={onSignOut} disabled={pending} className="menu-item border-t border-white/[0.07] text-slate-400"><LogOut className="h-4 w-4" />{pending ? "Signing out…" : "Sign out"}</button></div>; }

function FindDeals({ settings, savedIds, onOpen, onToggleSaved }: { settings: UserSettings; savedIds: string[]; onOpen: (deal: AppDeal) => void; onToggleSaved: (deal: AppDeal) => void }) {
  const [product, setProduct] = useState("Technology › Phones › Apple › iPhone › iPhone 15 Pro Max › 128GB");
  const [location, setLocation] = useState(settings.region); const [radius, setRadius] = useState(String(settings.defaultDistance)); const [budget, setBudget] = useState(String(settings.maxPurchase));
  const [advanced, setAdvanced] = useState(false); const [state, setState] = useState<SearchState>("results");
  const [sort, setSort] = useState("Best match"); const [risk, setRisk] = useState(settings.riskTolerance === "Medium" ? "Any risk" : settings.riskTolerance); const [minProfit, setMinProfit] = useState(String(settings.minProfit)); const [page, setPage] = useState(1);
  const filtered = useMemo(() => appDeals.filter((deal) => deal.cost <= Number(budget || Infinity) && deal.profit >= Number(minProfit) && (risk === "Any risk" || deal.risk === risk)).sort((a, b) => sort === "Highest profit" ? b.profit - a.profit : sort === "Highest ROI" ? b.roi - a.roi : 0), [budget, minProfit, risk, sort]);
  function search() { setState("loading"); window.setTimeout(() => { setPage(1); setState(product.toLowerCase().includes("error") ? "error" : product.toLowerCase().includes("nothing") ? "empty" : "results"); }, 850); }
  return <div className="space-y-7"><PageIntro title="Find your next profitable deal" copy="Choose a product, set your buying limits and compare opportunities with the evidence kept close." />
    <section className="surface p-4 sm:p-5" aria-label="Deal search"><div className="grid gap-4 xl:grid-cols-[minmax(300px,1.5fr)_1fr_140px_160px]"><ProductPicker value={product} setValue={setProduct} /><Field label="Location"><div className="relative"><MapPin className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" /><input value={location} onChange={(e) => setLocation(e.target.value)} className="input pl-10" /></div></Field><Field label="Radius"><select value={radius} onChange={(e) => setRadius(e.target.value)} className="input"><option value="5">5 miles</option><option value="10">10 miles</option><option value="25">25 miles</option><option value="50">50 miles</option><option value="100">100 miles</option></select></Field><Field label="Budget"><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-sm text-slate-500">£</span><input aria-label="Maximum budget" type="number" min="0" value={budget} onChange={(e) => setBudget(e.target.value)} className="input pl-7" /></div></Field></div>
      <button onClick={() => setAdvanced((v) => !v)} className="mt-4 flex min-h-10 items-center gap-2 text-sm font-medium text-slate-400 hover:text-white" aria-expanded={advanced}><SlidersHorizontal className="h-4 w-4" />Advanced filters<ChevronDown className={cn("h-4 w-4 transition", advanced && "rotate-180")} /></button>
      {advanced && <div className="grid gap-4 border-t border-white/[0.07] pt-4 sm:grid-cols-3"><Field label="Minimum profit"><select value={minProfit} onChange={(e) => setMinProfit(e.target.value)} className="input"><option value="0">Any profit</option><option value="25">£25+</option><option value="50">£50+</option><option value="100">£100+</option></select></Field><Field label="Risk level"><select value={risk} onChange={(e) => setRisk(e.target.value)} className="input"><option>Any risk</option><option>Low</option><option>Medium</option><option>High</option></select></Field><Field label="Sort results"><select value={sort} onChange={(e) => setSort(e.target.value)} className="input"><option>Best match</option><option>Highest profit</option><option>Highest ROI</option><option>Newest first</option></select></Field></div>}
      <div className="mt-5 flex flex-col gap-3 border-t border-white/[0.07] pt-5 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs leading-5 text-slate-500">Results shown here are representative while the live finder connection is completed.</p><button onClick={search} disabled={state === "loading" || !product || !location} className="primary-button min-h-12 px-6">{state === "loading" ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}{state === "loading" ? "Searching…" : "Find deals"}</button></div>
    </section>
    {state === "loading" && <ResultsSkeleton />}
    {state === "error" && <StatePanel icon={AlertTriangle} title="The finder could not load results" copy="Your search is safe. Try again, or adjust the product and location." action="Try again" onAction={search} tone="danger" />}
    {state === "empty" || (state === "results" && !filtered.length) ? <StatePanel icon={ListFilter} title="No deals match these filters" copy="Increase the budget or radius, or remove a profit or risk limit." action="Reset filters" onAction={() => { setBudget("650"); setMinProfit("0"); setRisk("Any risk"); setState("results"); }} /> : null}
    {state === "ready" && <StatePanel icon={PackageSearch} title="Start with a product" copy="Choose a category or exact model to find matching opportunities." />}
    {state === "results" && filtered.length > 0 && <><Results deals={filtered} savedIds={savedIds} onOpen={onOpen} onToggleSaved={onToggleSaved} /><div className="flex items-center justify-between border-t border-white/[0.07] pt-5"><p className="text-xs text-slate-500">Page {page} of 3</p><div className="flex gap-2"><button className="secondary-button" disabled={page === 1} onClick={() => setPage((n) => Math.max(1, n - 1))}>Previous</button><button className="secondary-button" disabled={page === 3} onClick={() => setPage((n) => Math.min(3, n + 1))}>Next</button></div></div></>}
  </div>;
}

function ProductPicker({ value, setValue }: { value: string; setValue: (value: string) => void }) { const [open, setOpen] = useState(false); const [query, setQuery] = useState(""); const ref = useRef<HTMLDivElement>(null); useEffect(() => { function close(e: MouseEvent) { if (!ref.current?.contains(e.target as Node)) setOpen(false); } document.addEventListener("mousedown", close); return () => document.removeEventListener("mousedown", close); }, []); const visible = query ? flattenTaxonomy(taxonomy).filter((path) => path.toLowerCase().includes(query.toLowerCase())) : []; return <Field label="Product"><div className="relative" ref={ref}><button type="button" onClick={() => setOpen((v) => !v)} className="input flex items-center justify-between gap-3 text-left" aria-expanded={open}><span className="truncate">{value || "Choose a category or product"}</span><ChevronDown className="h-4 w-4 shrink-0 text-slate-500" /></button>{open && <div className="absolute left-0 right-0 top-[calc(100%+8px)] z-30 max-h-[420px] overflow-auto rounded-2xl border border-white/[0.1] bg-[#090c14] p-3 shadow-[0_24px_70px_rgba(0,0,0,.55)]"><div className="relative mb-3"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" /><input autoFocus value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search products and categories" className="input pl-10" /></div>{query ? <div className="space-y-1">{visible.length ? visible.map((path) => <button key={path} onClick={() => { setValue(path); setOpen(false); }} className="menu-item">{path}</button>) : <p className="p-4 text-center text-sm text-slate-500">No matching products</p>}</div> : <div className="space-y-1">{taxonomy.map((node) => <TaxonomyNode key={node.name} node={node} path={[]} select={(path) => { setValue(path); setOpen(false); }} />)}</div>}</div>}</div></Field>; }
function TaxonomyNode({ node, path, select }: { node: Taxon; path: string[]; select: (path: string) => void }) { const [open, setOpen] = useState(false); const full = [...path, node.name]; return <div><div className="flex"><button onClick={() => select(full.join(" › "))} className="menu-item flex-1">{node.name}</button>{node.children && <button onClick={() => setOpen((v) => !v)} className="control h-10 w-10" aria-label={`${open ? "Collapse" : "Expand"} ${node.name}`}><ChevronRight className={cn("h-4 w-4 transition", open && "rotate-90")} /></button>}</div>{open && node.children && <div className="ml-3 border-l border-white/[0.08] pl-2">{node.children.map((child) => <TaxonomyNode key={child.name} node={child} path={full} select={select} />)}</div>}</div>; }
function flattenTaxonomy(nodes: Taxon[], parent: string[] = []): string[] { return nodes.flatMap((node) => { const path = [...parent, node.name]; return [path.join(" › "), ...(node.children ? flattenTaxonomy(node.children, path) : [])]; }); }

function Results({ deals, savedIds, onOpen, onToggleSaved }: { deals: AppDeal[]; savedIds: string[]; onOpen: (deal: AppDeal) => void; onToggleSaved: (deal: AppDeal) => void }) { return <section aria-labelledby="results-heading"><div className="mb-4 flex items-end justify-between"><div><h2 id="results-heading" className="text-xl font-semibold">Strongest opportunities</h2><p className="mt-1 text-xs text-slate-500">Representative results ranked using margin, demand, risk and freshness.</p></div><span className="hidden text-xs text-slate-500 sm:block">{deals.length} shown</span></div><div className="grid gap-4 xl:grid-cols-2">{deals.map((deal, index) => <DealCard key={deal.id} deal={deal} eager={index < 2} saved={savedIds.includes(deal.id)} onOpen={() => onOpen(deal)} onToggleSaved={() => onToggleSaved(deal)} />)}</div></section>; }
function DealCard({ deal, eager, saved, onOpen, onToggleSaved }: { deal: AppDeal; eager: boolean; saved: boolean; onOpen: () => void; onToggleSaved: () => void }) { const score = dealScore(deal); return <article className="group overflow-hidden rounded-2xl border border-white/[0.08] bg-[#060911] transition hover:border-blue-300/20"><div className="flex min-h-[196px] flex-col sm:flex-row"><button onClick={onOpen} className="relative min-h-44 w-full overflow-hidden bg-white/[0.03] text-left sm:w-48" aria-label={`View ${deal.title}`}><Image src={deal.image} alt={deal.title} fill loading={eager ? "eager" : "lazy"} className="object-cover transition duration-500 group-hover:scale-[1.025]" sizes="(max-width: 640px) 100vw, 192px" /></button><div className="flex min-w-0 flex-1 flex-col p-4"><div className="flex items-start gap-3"><button onClick={onOpen} className="min-w-0 flex-1 text-left"><p className="truncate text-xs font-medium text-blue-200">{deal.marketplace} · {deal.age}</p><h3 className="mt-1 line-clamp-2 font-semibold leading-6">{deal.title}</h3><p className="mt-1 text-xs text-slate-500">{deal.location} · {deal.risk} risk</p></button><button onClick={onToggleSaved} className={cn("control shrink-0", saved && "border-blue-300/25 bg-blue-500/12 text-blue-100")} aria-label={saved ? `Remove ${deal.title} from saved deals` : `Save ${deal.title}`}><Bookmark className={cn("h-4 w-4", saved && "fill-current")} /></button></div><div className="mt-auto grid grid-cols-4 gap-2 pt-4"><Metric label="Buy" value={`£${deal.cost}`} /><Metric label="Resale" value={`£${deal.resale}`} /><Metric label="Profit" value={`£${deal.profit}`} good /><Metric label="ROI" value={`${deal.roi}%`} good /></div><button onClick={onOpen} className="mt-3 flex items-center justify-between text-xs font-semibold text-slate-400 hover:text-white"><span>Flip Score {score} · {deal.demand} demand</span><span className="flex items-center gap-1 text-blue-200">Inspect <ChevronRight className="h-3.5 w-3.5" /></span></button></div></div></article>; }
function Metric({ label, value, good }: { label: string; value: string; good?: boolean }) { return <div><p className={cn("text-sm font-semibold tabular-nums", good && "text-emerald-300")}>{value}</p><p className="mt-0.5 text-[10px] text-slate-500">{label}</p></div>; }
function ResultsSkeleton() { return <div aria-label="Searching for deals" aria-busy="true" className="grid gap-4 xl:grid-cols-2">{[1, 2, 3, 4].map((n) => <div key={n} className="h-48 animate-pulse rounded-2xl border border-white/[0.06] bg-white/[0.025]" />)}</div>; }

function Scanner({ onOpen }: { onOpen: (deal: AppDeal) => void }) { const [state, setState] = useState<ScanState>("ready"); const [preview, setPreview] = useState<string | null>(null); const [name, setName] = useState(""); const fileRef = useRef<HTMLInputElement>(null); const deal = appDeals[2]; function choose(file?: File) { if (!file) return; if (!file.type.startsWith("image/")) { setState("error"); return; } setPreview(URL.createObjectURL(file)); setState("preview"); } function analyse() { if (!preview && !name.trim()) return; setState("analysing"); window.setTimeout(() => setState(name.toLowerCase().includes("unknown") ? "error" : "identified"), 1100); } function reset() { if (preview) URL.revokeObjectURL(preview); setPreview(null); setName(""); setState("ready"); } return <div className="space-y-7"><PageIntro title="Scan a product before you buy" copy="Add a clear photo or enter a product name, then review the match before opening its valuation." />
    <div className="grid gap-5 xl:grid-cols-[1fr_.85fr]"><section className="surface p-5 sm:p-8"><input ref={fileRef} type="file" accept="image/*" className="sr-only" onChange={(e) => choose(e.target.files?.[0])} />
      {state === "ready" && <div className="grid min-h-[390px] place-items-center text-center"><div className="max-w-lg"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-blue-500/12 text-blue-200"><Upload className="h-6 w-6" /></span><h2 className="mt-5 text-xl font-semibold">Add a product photo</h2><p className="mt-2 text-sm leading-6 text-slate-400">Use a clear image showing the whole item, logo and model markings. The photo is only needed for identification.</p><button onClick={() => fileRef.current?.click()} className="primary-button mx-auto mt-6 min-h-12 px-5"><FileImage className="h-4 w-4" />Choose photo</button><div className="my-5 flex items-center gap-3 text-xs text-slate-600"><span className="h-px flex-1 bg-white/[0.07]" />or<span className="h-px flex-1 bg-white/[0.07]" /></div><div className="flex flex-col gap-2 sm:flex-row"><input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Sony WH-1000XM5" className="input" /><button onClick={analyse} disabled={!name.trim()} className="secondary-button shrink-0">Identify item</button></div></div></div>}
      {state === "preview" && <div><div className="relative aspect-[4/3] max-h-[430px] overflow-hidden rounded-2xl bg-black"><Image src={preview!} alt="Selected product preview" fill unoptimized className="object-contain" /></div><div className="mt-4 flex flex-wrap gap-2"><button onClick={analyse} className="primary-button"><Sparkles className="h-4 w-4" />Analyse photo</button><button onClick={() => fileRef.current?.click()} className="secondary-button"><RefreshCw className="h-4 w-4" />Choose another</button><button onClick={reset} className="secondary-button"><Trash2 className="h-4 w-4" />Remove</button></div></div>}
      {state === "analysing" && <div className="grid min-h-[390px] place-items-center text-center" aria-live="polite"><div><LoaderCircle className="mx-auto h-10 w-10 animate-spin text-blue-300" /><h2 className="mt-5 text-xl font-semibold">Identifying the product</h2><p className="mt-2 text-sm text-slate-400">Checking visible markings and matching likely models…</p><div className="mx-auto mt-6 h-1.5 w-64 overflow-hidden rounded-full bg-white/[0.08]"><div className="h-full w-2/3 animate-pulse rounded-full bg-blue-500" /></div></div></div>}
      {state === "identified" && <div className="grid min-h-[390px] place-items-center"><div className="w-full max-w-lg text-center"><BadgeCheck className="mx-auto h-10 w-10 text-emerald-300" /><p className="mt-4 text-xs font-semibold uppercase tracking-[0.16em] text-emerald-300">Likely match</p><h2 className="mt-2 text-2xl font-semibold">{name.trim() || "Sony WH-1000XM5"}</h2><p className="mt-2 text-sm text-slate-400">Representative product match · Confirm the exact model</p><div className="mt-5 rounded-xl border border-white/[0.08] bg-white/[0.025] p-4 text-left text-sm text-slate-400"><strong className="text-white">Preview match.</strong> Check the model label and condition before relying on a valuation.</div><div className="mt-5 flex flex-col gap-2 sm:flex-row"><button onClick={() => onOpen(name.trim() ? { ...deal, id: "scanner-preview", title: name.trim() } : deal)} className="primary-button flex-1">Open valuation</button><button onClick={reset} className="secondary-button flex-1">That is not it</button></div></div></div>}
      {state === "error" && <div className="grid min-h-[390px] place-items-center"><StatePanel bare icon={ImageOff} title="We could not identify this item" copy="Try another angle with the whole product and model markings visible, or enter its name manually." action="Try another photo" onAction={reset} tone="danger" /></div>}
    </section><aside className="surface p-5"><h2 className="font-semibold">Before you scan</h2><ul className="mt-4 space-y-3 text-sm leading-6 text-slate-400"><Tip text="Show the complete product, not only the packaging." /><Tip text="Include labels, logos and model numbers." /><Tip text="Avoid glare, blur and heavy shadows." /><Tip text="Confirm the suggested match before trusting a valuation." /></ul><div className="mt-6 border-t border-white/[0.07] pt-5"><div className="flex gap-3"><ShieldCheck className="mt-0.5 h-5 w-5 text-blue-200" /><p className="text-sm leading-6 text-slate-400">Scanner photos are processed for identification and are not intended to be retained.</p></div></div></aside></div>
  </div>; }
function Tip({ text }: { text: string }) { return <li className="flex gap-3"><Check className="mt-1 h-4 w-4 shrink-0 text-emerald-300" />{text}</li>; }

function Saved({ deals, meta, setMeta, unlockedIds, onOpen, onToggleSaved, onFind }: { deals: AppDeal[]; meta: SavedMeta; setMeta: React.Dispatch<React.SetStateAction<SavedMeta>>; unlockedIds: string[]; onOpen: (deal: AppDeal) => void; onToggleSaved: (deal: AppDeal) => void; onFind: () => void }) { const [query, setQuery] = useState(""); const [status, setStatus] = useState("All statuses"); const [sort, setSort] = useState("Recently saved"); const filtered = deals.filter((deal) => deal.title.toLowerCase().includes(query.toLowerCase()) && (status === "All statuses" || meta[deal.id]?.status === status)).sort((a, b) => sort === "Highest profit" ? b.profit - a.profit : sort === "Highest ROI" ? b.roi - a.roi : 0); return <div className="space-y-7"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><PageIntro title="Saved Deals" copy="Track promising listings, record your next step and keep valuation evidence together." /><button onClick={onFind} className="primary-button">Find more deals</button></div>{deals.length ? <><div className="surface grid gap-3 p-3 md:grid-cols-[1fr_180px_180px]"><Field label="Search"><div className="relative"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search saved deals" className="input pl-10" /></div></Field><Field label="Status"><select className="input" value={status} onChange={(e) => setStatus(e.target.value)}><option>All statuses</option><option>Interested</option><option>Contacted</option><option>Purchased</option><option>Passed</option></select></Field><Field label="Sort"><select className="input" value={sort} onChange={(e) => setSort(e.target.value)}><option>Recently saved</option><option>Highest profit</option><option>Highest ROI</option></select></Field></div><div className="grid gap-4 xl:grid-cols-2">{filtered.map((deal) => <SavedDeal key={deal.id} deal={deal} data={meta[deal.id] || { status: "Interested", note: "" }} unlocked={unlockedIds.includes(deal.id)} onOpen={() => onOpen(deal)} onRemove={() => onToggleSaved(deal)} onChange={(data) => setMeta((all) => ({ ...all, [deal.id]: data }))} />)}</div>{!filtered.length && <StatePanel icon={Search} title="No saved deals match" copy="Clear the search or choose another status." action="Clear filters" onAction={() => { setQuery(""); setStatus("All statuses"); }} />}</> : <StatePanel icon={Bookmark} title="No saved deals yet" copy="Save a result from Find a Deal or Scanner and it will appear here." action="Find a deal" onAction={onFind} />}</div>; }
function SavedDeal({ deal, data, unlocked, onOpen, onRemove, onChange }: { deal: AppDeal; data: { status: SavedStatus; note: string }; unlocked: boolean; onOpen: () => void; onRemove: () => void; onChange: (data: { status: SavedStatus; note: string }) => void }) { return <article className="surface overflow-hidden"><div className="flex gap-4 border-b border-white/[0.07] p-4"><button onClick={onOpen} className="relative h-20 w-20 shrink-0 overflow-hidden rounded-xl bg-white/[0.03]"><Image src={deal.image} alt={deal.title} fill className="object-cover" sizes="80px" /></button><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><button onClick={onOpen} className="text-left"><h2 className="line-clamp-2 font-semibold">{deal.title}</h2><p className="mt-1 text-xs text-slate-500">£{deal.cost} · {deal.location} · {deal.age}</p></button><button onClick={onRemove} className="control shrink-0" aria-label={`Remove ${deal.title}`}><X className="h-4 w-4" /></button></div><div className="mt-2 flex flex-wrap gap-2"><span className="badge text-emerald-200">£{deal.profit} profit</span>{unlocked && <span className="badge text-blue-200"><LockKeyhole className="h-3 w-3" />Buyer price unlocked</span>}</div></div></div><div className="grid gap-3 p-4 sm:grid-cols-[160px_1fr]"><Field label="Next step"><select className="input" value={data.status} onChange={(e) => onChange({ ...data, status: e.target.value as SavedStatus })}><option>Interested</option><option>Contacted</option><option>Purchased</option><option>Passed</option></select></Field><Field label="Notes"><input className="input" value={data.note} onChange={(e) => onChange({ ...data, note: e.target.value })} placeholder="Condition, seller response or next action" /></Field></div></article>; }

function DealSheet({ deal, saved, unlocked, close, toggleSaved, requestUnlock }: { deal: AppDeal; saved: boolean; unlocked: boolean; close: () => void; toggleSaved: () => void; requestUnlock: () => void }) { const score = dealScore(deal); return <div className="fixed inset-0 z-[60] bg-black/70" onMouseDown={close}><aside role="dialog" aria-modal="true" aria-labelledby="deal-title" onMouseDown={(e) => e.stopPropagation()} className="absolute inset-y-0 right-0 w-full overflow-y-auto border-l border-white/[0.09] bg-[#050810] shadow-[-24px_0_70px_rgba(0,0,0,.45)] sm:max-w-[660px]"><div className="sticky top-0 z-10 flex h-16 items-center justify-between border-b border-white/[0.08] bg-[#050810]/95 px-5"><p className="font-semibold">Deal inspection</p><button onClick={close} className="control" aria-label="Close deal inspection"><X className="h-5 w-5" /></button></div><div className="p-5 sm:p-7"><div className="flex gap-4"><div className="relative h-24 w-24 shrink-0 overflow-hidden rounded-2xl bg-white/[0.03]"><Image src={deal.image} alt={deal.title} fill className="object-cover" sizes="96px" /></div><div className="min-w-0"><h2 id="deal-title" className="text-xl font-semibold leading-7">{deal.title}</h2><p className="mt-2 text-sm text-slate-500">{deal.location} · listed {deal.age} ago</p><a href={deal.listingUrl || `https://www.ebay.co.uk/sch/i.html?_nkw=${encodeURIComponent(deal.title)}`} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-1.5 text-sm font-semibold text-blue-200 hover:text-white">Open source listing <ExternalLink className="h-4 w-4" /></a></div></div>
      <div className="mt-7 grid grid-cols-2 gap-3 sm:grid-cols-4"><DetailMetric label="Asking price" value={`£${deal.cost}`} /><DetailMetric label="Resale range" value={`£${deal.resale - 10}–£${deal.resale + 10}`} /><DetailMetric label="Expected profit" value={`£${deal.profit}`} good /><DetailMetric label="Expected ROI" value={`${deal.roi}%`} good /></div>
      <section className="mt-7 border-y border-white/[0.08] py-6"><div className="flex items-center justify-between gap-5"><div><h3 className="font-semibold">Flip Score</h3><p className="mt-1 text-sm leading-6 text-slate-500">A comparison aid based on margin, demand, risk and freshness—not a guarantee.</p></div><span className="text-3xl font-semibold text-blue-200">{score}</span></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-white/[0.08]"><div className="h-full rounded-full bg-blue-500" style={{ width: `${score}%` }} /></div><div className="mt-4 grid grid-cols-2 gap-3"><Info label="Confidence" value={score > 85 ? "High" : "Medium"} /><Info label="Risk" value={`${deal.risk} · ${deal.demand} demand`} /></div></section>
      <section className="py-6"><h3 className="font-semibold">Why this could work</h3><div className="mt-3 grid gap-3 sm:grid-cols-2"><Reason icon={TrendingUp} title="Healthy resale margin" text={`The representative resale range leaves roughly £${deal.profit} after estimated fees.`} /><Reason icon={Clock3} title="Fresh opportunity" text={`The listing was first seen ${deal.age} ago, so availability should be checked quickly.`} /></div><div className="mt-3 rounded-xl border border-amber-300/15 bg-amber-400/[0.05] p-4"><div className="flex gap-3"><ShieldAlert className="mt-0.5 h-5 w-5 shrink-0 text-amber-200" /><div><p className="text-sm font-semibold">Checks before buying</p><p className="mt-1 text-sm leading-6 text-slate-400">Confirm condition, ownership locks, included accessories and that the seller’s photos match the item.</p></div></div></div></section>
      <section className="border-t border-white/[0.08] py-6"><h3 className="font-semibold">Comparable sold evidence</h3><p className="mt-1 text-xs text-slate-500">Representative layout while live pricing evidence is connected.</p><div className="mt-3 divide-y divide-white/[0.07] rounded-2xl border border-white/[0.08]">{[deal.resale - 12, deal.resale + 8, deal.resale - 4].map((price, index) => <div key={price} className="flex items-center justify-between p-4 text-sm"><span className="text-slate-400">Used · sold {index + 2} days ago</span><span className="font-semibold tabular-nums">£{price}</span></div>)}</div></section>
      <section className="rounded-2xl border border-blue-300/15 bg-blue-500/[0.055] p-5"><div className="flex gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-blue-500/12 text-blue-200">{unlocked ? <ShieldCheck className="h-5 w-5" /> : <LockKeyhole className="h-5 w-5" />}</span><div><h3 className="font-semibold">Instant buyer price</h3><p className="mt-1 text-sm leading-6 text-slate-400">{unlocked ? "Unlocked for this saved deal." : "Preview how an eligible instant resale offer will appear once live credit pricing is set."}</p></div></div>{unlocked ? <div className="mt-4 flex items-end justify-between rounded-xl border border-emerald-300/15 bg-emerald-400/[0.06] p-4"><div><p className="text-xs text-slate-500">Representative instant offer</p><p className="mt-1 text-2xl font-semibold text-emerald-200">£{Math.max(1, deal.resale - 35)}</p></div><span className="text-xs text-slate-500">Saved</span></div> : <button onClick={requestUnlock} className="secondary-button mt-4 w-full">Preview unlock confirmation</button>}</section>
      <div className="sticky bottom-0 -mx-5 mt-7 flex gap-3 border-t border-white/[0.08] bg-[#050810]/95 px-5 py-4 sm:-mx-7 sm:px-7"><button onClick={toggleSaved} className={cn("secondary-button flex-1", saved && "border-blue-300/20 bg-blue-500/10 text-blue-100")}><Bookmark className={cn("h-4 w-4", saved && "fill-current")} />{saved ? "Saved" : "Save deal"}</button><a href={deal.listingUrl || `https://www.ebay.co.uk/sch/i.html?_nkw=${encodeURIComponent(deal.title)}`} target="_blank" rel="noreferrer" className="primary-button flex-1">View listing</a></div>
    </div></aside></div>; }
function Reason({ icon: Icon, title, text }: { icon: typeof TrendingUp; title: string; text: string }) { return <div className="rounded-xl border border-white/[0.07] bg-white/[0.025] p-4"><Icon className="h-5 w-5 text-blue-200" /><p className="mt-3 text-sm font-semibold">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{text}</p></div>; }
function DetailMetric({ label, value, good }: { label: string; value: string; good?: boolean }) { return <div className="rounded-xl border border-white/[0.07] bg-white/[0.025] p-3"><p className={cn("text-base font-semibold tabular-nums", good && "text-emerald-300")}>{value}</p><p className="mt-1 text-[11px] text-slate-500">{label}</p></div>; }
function UnlockDialog({ deal, cancel, confirm }: { deal: AppDeal; cancel: () => void; confirm: () => void }) { return <div className="fixed inset-0 z-[70] grid place-items-center bg-black/75 p-4"><div role="dialog" aria-modal="true" aria-labelledby="unlock-title" className="w-full max-w-md rounded-3xl border border-white/[0.1] bg-[#090c14] p-6 shadow-[0_24px_80px_rgba(0,0,0,.6)]"><WalletCards className="h-7 w-7 text-blue-200" /><h2 id="unlock-title" className="mt-5 text-xl font-semibold">Preview the unlock flow?</h2><p className="mt-2 text-sm leading-6 text-slate-400">This UI preview reveals representative buyer information for “{deal.title}” and saves the deal. No credits are deducted.</p><div className="mt-5 rounded-xl border border-white/[0.08] bg-white/[0.025] p-3 text-sm text-slate-300">The final GBP credit cost will be shown here before users confirm.</div><div className="mt-6 flex gap-3"><button onClick={cancel} className="secondary-button flex-1">Cancel</button><button onClick={confirm} className="primary-button flex-1">Preview unlock</button></div></div></div>; }

function Membership({ profile, credits, notify }: { profile: AccountProfile; credits: CreditSummary; notify: (message: string) => void }) { const total = credits.subscriptionCredits + credits.purchasedCredits; const expiry = credits.subscriptionCreditsExpireAt ? new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "long", year: "numeric" }).format(new Date(credits.subscriptionCreditsExpireAt)) : "No active monthly allowance"; return <SimpleAccount title="Membership & Credits" icon={CreditCard}><div className="grid gap-4 lg:grid-cols-3"><Info label="Current membership" value={profile.plan} /><Info label="Monthly credits" value={credits.subscriptionCredits.toLocaleString("en-GB")} /><Info label="Purchased credits" value={credits.purchasedCredits.toLocaleString("en-GB")} /></div><div className="mt-5 rounded-2xl border border-white/[0.08] bg-white/[0.025] p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs text-slate-500">Total available</p><p className="mt-1 text-3xl font-semibold tabular-nums">{total.toLocaleString("en-GB")}</p></div><p className="text-xs text-slate-400">Monthly balance: {expiry}</p></div><p className="mt-4 text-sm leading-6 text-slate-400">Monthly credits are used first and expire at the end of the subscription period. Purchased credits remain separate and do not expire while the account stays open.</p></div><section className="mt-7"><div className="flex items-end justify-between"><div><h3 className="font-semibold">Credit activity</h3><p className="mt-1 text-xs text-slate-500">Charges and restorations will appear here.</p></div></div>{total ? <div className="mt-3 rounded-xl border border-white/[0.07] p-4 text-sm text-slate-400">No credit activity yet.</div> : <StatePanel bare icon={History} title="No credit activity yet" copy="Your searches, unlocks, purchases and automatic restorations will be listed here." />}</section><button onClick={() => notify("Credit purchases will open when final GBP pricing and Stripe are connected.")} className="primary-button mt-6">View future credit packs</button><p className="mt-3 text-xs text-slate-500">No purchase can be made from this UI prototype.</p></SimpleAccount>; }

function AccountCenter({ profile, setProfile, notify }: { profile: AccountProfile; setProfile: React.Dispatch<React.SetStateAction<AccountProfile>>; notify: (message: string) => void }) { const router = useRouter(); const [draft, setDraft] = useState(profile); const [passwords, setPasswords] = useState({ current: "", next: "", confirm: "" }); const [showPasswords, setShowPasswords] = useState(false); const [deletion, setDeletion] = useState({ password: "", confirmation: "" }); const [pending, start] = useTransition(); function saveProfile() { start(async () => { const result = await updateProfileAction({ name: draft.name, username: draft.username, email: draft.email, location: draft.location, bio: draft.bio }); notify(result.message); if (result.ok) setProfile(draft); }); } function changePassword() { if (passwords.next !== passwords.confirm) return notify("The new passwords do not match."); start(async () => { const result = await updatePasswordAction(passwords.current, passwords.next); notify(result.message); if (result.ok) setPasswords({ current: "", next: "", confirm: "" }); }); } function remove() { start(async () => { const result = await deleteAccountAction(deletion.password, deletion.confirmation); notify(result.message); if (result.ok) router.push("/auth/sign-in?message=Your+Flipbot+account+was+deleted."); }); } return <SimpleAccount title="Profile & Security" icon={UserRound}><div className="grid gap-8 lg:grid-cols-2"><section><h3 className="font-semibold">Account details</h3><p className="mt-1 text-xs text-slate-500">Changing your email requires confirmation.</p><div className="mt-4 space-y-3"><Field label="Full name"><input className="input" value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} /></Field><Field label="Username"><input className="input" value={draft.username} onChange={(e) => setDraft({ ...draft, username: e.target.value.toLowerCase() })} /></Field><Field label="Email"><input className="input" type="email" value={draft.email} onChange={(e) => setDraft({ ...draft, email: e.target.value })} /></Field><Field label="Location"><input className="input" value={draft.location} onChange={(e) => setDraft({ ...draft, location: e.target.value })} /></Field><Field label="Bio"><textarea className="input min-h-24 py-3" maxLength={160} value={draft.bio} onChange={(e) => setDraft({ ...draft, bio: e.target.value })} /></Field><button disabled={pending} onClick={saveProfile} className="primary-button">{pending ? "Saving…" : "Save account details"}</button></div></section><section><div className="flex items-center justify-between"><h3 className="font-semibold">Password and sessions</h3><button onClick={() => setShowPasswords((v) => !v)} className="text-xs font-semibold text-blue-200">{showPasswords ? "Hide" : "Show"} passwords</button></div><div className="mt-4 space-y-3"><Field label="Current password"><input className="input" type={showPasswords ? "text" : "password"} autoComplete="current-password" value={passwords.current} onChange={(e) => setPasswords({ ...passwords, current: e.target.value })} /></Field><Field label="New password"><input className="input" type={showPasswords ? "text" : "password"} minLength={8} maxLength={128} autoComplete="new-password" value={passwords.next} onChange={(e) => setPasswords({ ...passwords, next: e.target.value })} /></Field><Field label="Confirm new password"><input className="input" type={showPasswords ? "text" : "password"} minLength={8} maxLength={128} autoComplete="new-password" value={passwords.confirm} onChange={(e) => setPasswords({ ...passwords, confirm: e.target.value })} /></Field><p className="text-xs leading-5 text-slate-500">At least 8 characters. Spaces and memorable passphrases are allowed; known leaked passwords are rejected.</p><div className="flex flex-wrap gap-2"><button disabled={pending || !passwords.current || !passwords.next} onClick={changePassword} className="secondary-button">Change password</button><button disabled={pending} onClick={() => start(async () => notify((await signOutOtherSessionsAction()).message))} className="secondary-button">Sign out other sessions</button></div></div></section></div><div className="mt-8 grid gap-5 border-t border-white/[0.08] pt-7 lg:grid-cols-2"><section><h3 className="font-semibold">Your information</h3><p className="mt-2 text-sm leading-6 text-slate-400">Download account, preferences, searches, results, consent history and credit records.</p><a href="/api/account/export" className="secondary-button mt-4"><Download className="h-4 w-4" />Download my data</a></section><section><h3 className="font-semibold text-red-200">Delete account</h3><p className="mt-2 text-sm leading-6 text-slate-400">Permanently removes your account and unused credits. Required billing and security records may be retained.</p><div className="mt-4 space-y-3"><Field label="Current password"><input className="input" type="password" value={deletion.password} onChange={(e) => setDeletion({ ...deletion, password: e.target.value })} /></Field><Field label="Type DELETE"><input className="input" value={deletion.confirmation} onChange={(e) => setDeletion({ ...deletion, confirmation: e.target.value })} /></Field><button disabled={pending || deletion.confirmation !== "DELETE" || !deletion.password} onClick={remove} className="danger-button"><Trash2 className="h-4 w-4" />Delete account permanently</button></div></section></div></SimpleAccount>; }

function SettingsCenter({ settings, setSettings, notify }: { settings: UserSettings; setSettings: React.Dispatch<React.SetStateAction<UserSettings>>; notify: (message: string) => void }) { const [draft, setDraft] = useState(settings); const [pending, start] = useTransition(); function save() { start(async () => { const result = await updateSettingsAction(draft); notify(result.message); if (result.ok) setSettings(draft); }); } return <SimpleAccount title="Settings" icon={Settings}><div className="grid gap-4 sm:grid-cols-2"><Field label="Default radius (miles)"><input className="input" type="number" min={1} max={100} value={draft.defaultDistance} onChange={(e) => setDraft({ ...draft, defaultDistance: Number(e.target.value) })} /></Field><Field label="Minimum profit (£)"><input className="input" type="number" min={0} value={draft.minProfit} onChange={(e) => setDraft({ ...draft, minProfit: Number(e.target.value) })} /></Field><Field label="Maximum purchase (£)"><input className="input" type="number" min={0} value={draft.maxPurchase} onChange={(e) => setDraft({ ...draft, maxPurchase: Number(e.target.value) })} /></Field><Field label="Region"><input className="input" value={draft.region} onChange={(e) => setDraft({ ...draft, region: e.target.value })} /></Field><Field label="Risk tolerance"><select className="input" value={draft.riskTolerance} onChange={(e) => setDraft({ ...draft, riskTolerance: e.target.value as UserSettings["riskTolerance"] })}><option>Low</option><option>Medium</option><option>High</option></select></Field><Field label="Card density"><select className="input" value={draft.compactCards ? "Compact" : "Comfortable"} onChange={(e) => setDraft({ ...draft, compactCards: e.target.value === "Compact" })}><option>Comfortable</option><option>Compact</option></select></Field></div><div className="mt-6 space-y-3"><Toggle checked={draft.emailAlerts} onChange={(v) => setDraft({ ...draft, emailAlerts: v })} title="Deal alerts" text="Receive alerts you explicitly configure for saved searches." /><Toggle checked={draft.marketingEmailOptIn} onChange={(v) => setDraft({ ...draft, marketingEmailOptIn: v })} title="Product news and offers" text="Optional marketing email. Essential account, security and billing messages are unaffected." /><Toggle checked={draft.reducedMotion} onChange={(v) => setDraft({ ...draft, reducedMotion: v })} title="Reduce motion" text="Minimise non-essential movement throughout the dashboard." /></div><button disabled={pending} onClick={save} className="primary-button mt-6">{pending ? "Saving…" : "Save settings"}</button></SimpleAccount>; }
function Toggle({ checked, onChange, title, text }: { checked: boolean; onChange: (value: boolean) => void; title: string; text: string }) { return <label className="flex cursor-pointer items-start gap-3 rounded-xl border border-white/[0.08] bg-white/[0.025] p-4 text-sm"><input type="checkbox" className="mt-1 h-4 w-4 accent-blue-500" checked={checked} onChange={(e) => onChange(e.target.checked)} /><span><strong className="block">{title}</strong><span className="mt-1 block leading-5 text-slate-400">{text}</span></span></label>; }

function HelpCenter({ navigate }: { navigate: (page: AppPage) => void }) { const [query, setQuery] = useState(""); const topics = [{ title: "Finding and filtering deals", text: "Choose a broad category or exact model, then narrow by location, budget, profit and risk." }, { title: "Understanding Flip Score", text: "Use the score to compare opportunities, then inspect the evidence and risks before buying." }, { title: "Credits and buyer prices", text: "Monthly and purchased credits are separate. Unlock costs will always be confirmed first." }, { title: "Scanner help", text: "Use a clear photo and confirm the suggested model before opening a valuation." }].filter((item) => `${item.title} ${item.text}`.toLowerCase().includes(query.toLowerCase())); return <SimpleAccount title="Help centre" icon={HelpCircle}><div className="relative"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search help" className="input pl-10" /></div><div className="mt-6 divide-y divide-white/[0.07] border-y border-white/[0.07]">{topics.map((topic) => <details key={topic.title} className="group py-4"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 font-semibold"><span>{topic.title}</span><ChevronDown className="h-4 w-4 text-slate-500 transition group-open:rotate-180" /></summary><p className="mt-3 max-w-2xl text-sm leading-7 text-slate-400">{topic.text}</p></details>)}</div>{!topics.length && <StatePanel bare icon={Search} title="No help topic found" copy="Try a shorter search or contact the Flipbot team." />}<div className="mt-7 flex flex-col gap-4 rounded-2xl border border-blue-300/15 bg-blue-500/[0.05] p-5 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="font-semibold">Still need help?</h3><p className="mt-1 text-sm text-slate-400">Describe what happened without including passwords or full card details.</p></div><a href="mailto:team@flipbot.me" className="primary-button shrink-0">Email support</a></div><div className="mt-5 flex flex-wrap gap-2 text-xs"><button onClick={() => navigate("profile")} className="secondary-button">Account security</button><a href="/legal/privacy" className="secondary-button">Privacy</a><a href="/legal/terms" className="secondary-button">Terms</a></div></SimpleAccount>; }

function Onboarding({ close, settings, setSettings, notify }: { close: () => void; settings: UserSettings; setSettings: React.Dispatch<React.SetStateAction<UserSettings>>; notify: (message: string) => void }) { const [step, setStep] = useState(1); const [draft, setDraft] = useState(settings); return <div className="fixed inset-0 z-[80] grid place-items-center bg-black/80 p-4"><div role="dialog" aria-modal="true" aria-labelledby="setup-title" className="w-full max-w-xl rounded-3xl border border-white/[0.1] bg-[#080b13] p-6 shadow-[0_24px_80px_rgba(0,0,0,.65)]"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-blue-200">Step {step} of 3</p><h2 id="setup-title" className="mt-2 text-2xl font-semibold">{step === 1 ? "Set your sourcing area" : step === 2 ? "Choose useful defaults" : "You are ready to search"}</h2></div><button onClick={close} className="control" aria-label="Close setup"><X className="h-5 w-5" /></button></div><div className="mt-5 flex gap-2" aria-hidden="true">{[1, 2, 3].map((n) => <span key={n} className={cn("h-1.5 flex-1 rounded-full bg-white/[0.08]", n <= step && "bg-blue-500")} />)}</div>{step === 1 && <div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Region"><input className="input" value={draft.region} onChange={(e) => setDraft({ ...draft, region: e.target.value })} /></Field><Field label="Default radius"><select className="input" value={draft.defaultDistance} onChange={(e) => setDraft({ ...draft, defaultDistance: Number(e.target.value) })}><option value="5">5 miles</option><option value="15">15 miles</option><option value="25">25 miles</option><option value="50">50 miles</option></select></Field></div>}{step === 2 && <div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Typical maximum spend"><input className="input" type="number" value={draft.maxPurchase} onChange={(e) => setDraft({ ...draft, maxPurchase: Number(e.target.value) })} /></Field><Field label="Minimum useful profit"><input className="input" type="number" value={draft.minProfit} onChange={(e) => setDraft({ ...draft, minProfit: Number(e.target.value) })} /></Field><Field label="Risk tolerance"><select className="input" value={draft.riskTolerance} onChange={(e) => setDraft({ ...draft, riskTolerance: e.target.value as UserSettings["riskTolerance"] })}><option>Low</option><option>Medium</option><option>High</option></select></Field></div>}{step === 3 && <div className="mt-6 rounded-2xl border border-emerald-300/15 bg-emerald-400/[0.05] p-5"><PackageCheck className="h-7 w-7 text-emerald-300" /><p className="mt-3 font-semibold">Your dashboard defaults are ready.</p><p className="mt-2 text-sm leading-6 text-slate-400">Estimates help compare deals but do not guarantee a sale or profit. Always inspect the item and seller evidence.</p></div>}<div className="mt-7 flex justify-between"><button onClick={step === 1 ? close : () => setStep((n) => n - 1)} className="secondary-button">{step === 1 ? "Skip for now" : "Back"}</button><button onClick={() => { if (step < 3) setStep((n) => n + 1); else { setSettings(draft); notify("Setup preferences saved"); close(); } }} className="primary-button">{step < 3 ? "Continue" : "Finish setup"}</button></div></div></div>; }

function SimpleAccount({ title, icon: Icon, children }: { title: string; icon: typeof UserRound; children: React.ReactNode }) { return <div className="max-w-4xl"><div className="mb-6 flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-xl bg-blue-500/10 text-blue-200"><Icon className="h-5 w-5" /></span><h2 className="text-2xl font-semibold tracking-[-0.035em] sm:text-3xl">{title}</h2></div><section className="surface p-5 sm:p-7">{children}</section></div>; }
function PageIntro({ title, copy }: { title: string; copy: string }) { return <section className="max-w-3xl"><h2 className="text-balance text-3xl font-semibold tracking-[-0.035em] sm:text-4xl">{title}</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-slate-400 sm:text-base">{copy}</p></section>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block min-w-0"><span className="mb-2 block text-xs font-medium text-slate-400">{label}</span>{children}</label>; }
function Info({ label, value }: { label: string; value: string }) { return <div className="rounded-xl border border-white/[0.07] bg-white/[0.025] p-3"><p className="text-[11px] text-slate-500">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>; }
function StatePanel({ icon: Icon, title, copy, action, onAction, tone, bare }: { icon: typeof Bookmark; title: string; copy: string; action?: string; onAction?: () => void; tone?: "danger"; bare?: boolean }) { return <div className={cn("grid min-h-64 place-items-center rounded-[26px] border border-dashed border-white/[0.1] bg-white/[0.015] p-8 text-center", bare && "min-h-0 border-0 bg-transparent p-4")}><div><Icon className={cn("mx-auto h-8 w-8 text-slate-600", tone === "danger" && "text-amber-300")} /><h3 className="mt-4 font-semibold">{title}</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-500">{copy}</p>{action && <button onClick={onAction} className="secondary-button mt-5">{action}</button>}</div></div>; }
function dealScore(deal: AppDeal) { return Math.min(98, Math.max(61, 72 + Math.round(deal.roi / 5) - (deal.risk === "High" ? 10 : deal.risk === "Medium" ? 4 : 0))); }
